import tkinter as tk
import random

class Snake:
    def __init__(self, canvas):
        self.canvas = canvas
        self.size = 10
        self.direction = 'Right'
        self.nextDirection = None
        self.body = self.generateInitialPosition()
        self.draw()

    def draw(self):
        self.canvas.delete("snake")
        for index, segment in enumerate(self.body):
            fill_color = "green" if index != 0 else "darkgreen"
            self.canvas.create_rectangle(segment, fill=fill_color, tag="snake")

    def changeDirection(self, newDirection):
        opposite_directions = {'Up': 'NAME_1', 'NAME_1': 'Up', 'Left': 'Right', 'Right': 'Left'}
        if newDirection != opposite_directions[self.direction]:
            self.nextDirection = newDirection

    def move(self):
        if self.nextDirection:
            self.direction = self.nextDirection
            self.nextDirection = None

        head = self.body[0]
        x1, y1, x2, y2 = head
        if self.direction == 'Up':
            newHead = (x1, y1 - self.size, x2, y2 - self.size)
        elif self.direction == 'NAME_1':
            newHead = (x1, y1 + self.size, x2, y2 + self.size)
        elif self.direction == 'Left':
            newHead = (x1 - self.size, y1, x2 - self.size, y2)
        else:
            newHead = (x1 + self.size, y1, x2 + self.size, y2)
        self.body.insert(0, newHead)

        self.canvas.delete("snake")
        self.draw()
        self.canvas.delete(self.canvas.find_withtag("snake")[-1])
        self.body.pop(-1)

    def checkCollision(self):
        x1, y1, x2, y2 = self.body[0]
        return x1 < 0 or x2 > 500 or y1 < 0 or y2 > 500

    def checkSelfCollision(self):
        head = self.body[0]
        return any(segment == head for segment in self.body[1:])

    def grow(self):
        self.move()

    def generateInitialPosition(self):
        safe_margin = 5
        x = random.randint(safe_margin, 49 - safe_margin) * self.size
        y = random.randint(safe_margin, 49 - safe_margin) * self.size
        return [(x, y, x + self.size, y + self.size),
                (x - self.size, y, x, y + self.size),
                (x - 2 * self.size, y, x - self.size, y + self.size)]

    def resetSnake(self):
        self.direction = 'Right'
        self.nextDirection = None
        self.body = self.generateInitialPosition()
        self.draw()
